const menu=document.querySelector('.menu-toggle');
const languageForm=document.querySelector('#language-form');
if(languageForm){languageForm.addEventListener('submit',event=>{if(languageForm.elements.tl.value==='en'){event.preventDefault();document.querySelector('#language-status').textContent='You are already viewing the English original.';}});}
menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));document.querySelector('#main-nav').classList.toggle('open',!expanded);});
const catalogue=document.querySelector('.catalogue');
if(catalogue){let category='All';const cards=[...catalogue.querySelectorAll('.product-card')];const search=document.querySelector('#product-search');const filter=()=>{let count=0;cards.forEach(card=>{const visible=(category==='All'||card.dataset.group===category)&&(card.dataset.search||card.dataset.name).includes(search.value.trim().toLowerCase());card.hidden=!visible;if(visible)count++;});catalogue.querySelector('.catalogue-status').textContent=`${count} product${count===1?'':'s'}`;catalogue.querySelector('.empty-state').hidden=count>0;};catalogue.querySelectorAll('.filter').forEach(btn=>btn.addEventListener('click',()=>{category=btn.dataset.filter;catalogue.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn));});filter();}));search.addEventListener('input',filter);}
const form=document.querySelector('#enquiry-form');
if(form){const query=new URLSearchParams(location.search);if([...form.product.options].some(o=>o.value===query.get('product')))form.product.value=query.get('product');if(['buy','supply','general'].includes(query.get('intent')))form.intent.value=query.get('intent');const status=document.querySelector('#form-status');
const productOptions=[...form.product.options].map(option=>option.cloneNode(true));
const productNote=document.querySelector('#product-choice-note');
const filterProducts=()=>{
 const selected=form.product.value;
 const trade=form.intent.value==='buy'?'export':form.intent.value==='supply'?'import':null;
 const matching=productOptions.filter(option=>!trade||!option.dataset.trade||option.dataset.trade===trade);
 form.product.replaceChildren(...matching.map(option=>option.cloneNode(true)));
 form.product.value=matching.some(option=>option.value===selected)?selected:'';
 const count=matching.filter(option=>option.dataset.trade).length;
 if(productNote)productNote.textContent=trade?`Showing ${count} ${trade} products. Choose “Discuss another requirement” to see all products.`:`Showing all ${count} products.`;
};
form.intent.addEventListener('change',filterProducts);filterProducts();
const message=()=>{const d=new FormData(form);const product=form.product.selectedOptions[0].textContent;return `Shiva Exim trade enquiry\n\nName: ${d.get('name')}\nCompany: ${d.get('company')||'Not specified'}\nEmail: ${d.get('email')||'Not specified'}\nPhone: ${d.get('phone')||'Not specified'}\nEnquiry: ${form.intent.selectedOptions[0].textContent}\nProduct: ${d.get('product')?product:'Not specified'}\nQuantity: ${d.get('quantity')||'Not specified'}\nDestination / origin: ${d.get('destination')||'Not specified'}\n\nRequirements:\n${d.get('details')}`;};form.addEventListener('submit',event=>{event.preventDefault();const text=message();if(event.submitter?.value==='whatsapp'){window.open(`https://wa.me/919099666604?text=${encodeURIComponent(text)}`,'_blank','noopener');status.textContent='WhatsApp draft opened. Review it and press Send in WhatsApp to send your enquiry.';}else{const product=form.product.value?form.product.selectedOptions[0].textContent:'General';location.href=`mailto:info@shivaexim.com?subject=${encodeURIComponent(product+' enquiry — Shiva Exim')}&body=${encodeURIComponent(text)}`;status.textContent='Email draft requested. Review and send it in your email app. If no app opens, use Copy enquiry below.';}});document.querySelector('#copy-enquiry').addEventListener('click',async()=>{if(!form.reportValidity())return;const text=message();try{await navigator.clipboard.writeText(text);status.textContent='Enquiry copied. Paste it into your email or WhatsApp and send it to Shiva Exim.';}catch{const fallback=document.querySelector('#copy-fallback');fallback.hidden=false;fallback.value=text;fallback.focus();fallback.select();status.textContent='Select and copy the enquiry below, then paste it into your email or WhatsApp.';}});}
